import java.util.*;

class Solution {
    public List<Integer> topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>();
        for (int x : nums) freq.merge(x, 1, Integer::sum);
        List<Integer> vals = new ArrayList<>(freq.keySet());
        // more frequent first; on a tie, the smaller value first
        Collections.sort(vals, (a, b) -> {
            int fa = freq.get(a), fb = freq.get(b);
            return fa != fb ? Integer.compare(fb, fa) : Integer.compare(a, b);
        });
        return new ArrayList<>(vals.subList(0, k));
    }
}

