function topKFrequent(nums, k) {
  const m = new Map(); for (const x of nums) m.set(x, (m.get(x) || 0) + 1);
  return [...m.keys()].sort((a, b) => (m.get(b) - m.get(a)) || (a - b)).slice(0, k);
}
